int[] tree;
int n;
public NumArray(int[] nums) {
    if (nums.length > 0) {
        n = nums.length;
        tree = new int[n * 2];
        buildTree(nums);
    }
}
private void buildTree(int[] nums) {
    for (int i = n, j = 0;  i < 2 * n; i++,  j++)
        tree[i] = nums[j];
    for (int i = n - 1; i > 0; --i)
        tree[i] = tree[i * 2] + tree[i * 2 + 1];
}

void update(int pos, int val) {
    pos += n;
    tree[pos] = val;
    while (pos > 0) {
        int left = pos;
        int right = pos;
        if (pos % 2 == 0) {
            right = pos + 1;
        } else {
            left = pos - 1;
        }
        // parent is updated after child is updated
        tree[pos / 2] = tree[left] + tree[right];
        pos /= 2;
    }
}

public int sumRange(int l, int r) {
    // get leaf with value 'l'
    l += n;
    // get leaf with value 'r'
    r += n;
    int sum = 0;
    while (l <= r) {
        if ((l % 2) == 1) {
           sum += tree[l];
           l++;
        }
        if ((r % 2) == 0) {
           sum += tree[r];
           r--;
        }
        l /= 2;
        r /= 2;
    }
    return sum;
}

// Using Segment tree
//Editorial: https://leetcode.com/problems/range-sum-query-mutable/discuss/1218358/C%2B%2B-or-Segment-Tree-or-Explained
class NumArray {
public:
    vector<int> seg,arr;
    int n;
    void build(int idx,int low,int high)
    {
        if(low==high)
        {
            seg[idx]=arr[low];
            return;
        }
        int mid=(low+high)/2;
        build(2*idx+1,low,mid);
        build(2*idx+2,mid+1,high);
        seg[idx]=(seg[2*idx+1]+seg[2*idx+2]);
    }
    void updateUtil(int pos,int low,int high,int index,int val)
    {
        if(index>high or index<low)
            return;
        if(low==high)
        {
            if(low==index)
            {
                seg[pos]=val;
            }
            return;
        }
        int mid=(low+high)/2;
        updateUtil(2*pos+1,low,mid,index,val);
        updateUtil(2*pos+2,mid+1,high,index,val);
        seg[pos]=seg[2*pos+1]+seg[pos*2+2];
    }
    int rangesum(int pos,int low,int high,int left,int right)
    {
        if(left<=low and high<=right)
            return seg[pos];
        if(high<left or low>right)
            return 0;
        int mid=(low+high)/2;
        return rangesum(2*pos+1,low,mid,left,right)+rangesum(2*pos+2,mid+1,high,left,right);
    }
    NumArray(vector<int>& nums) {
        arr=nums;
        n=nums.size();
        seg.resize(4*n,0);
        build(0,0,n-1);
    }

    void update(int index, int val) {
        updateUtil(0,0,n-1,index,val);
    }

    int sumRange(int left, int right) {
        return rangesum(0,0,n-1,left,right);
    }
};
// Using Fenwick tree
//Editorial: https://leetcode.com/problems/range-sum-query-mutable/discuss/927800/Segment-Tree-and-Binary-Indexed-Tree-Solution-C%2B%2B
class NumArray {
public:
    vector<int> bit,arr;
    void init(int i,int x)
    {
        i++;
        while(i<bit.size())
        {
            bit[i]+=x;
            i+=(i&-i);
        }
    }
    int sum(int i)
    {
        i++;
        int ans=0;
        while(i>0)
        {
            ans+=bit[i];
            i-=(i&-i);
        }
        return ans;
    }
    NumArray(vector<int>& nums) {
        arr=nums;
        int n=nums.size();
        bit.resize(n+1,0);
        for(int i=0;i<nums.size();i++)
            init(i,nums[i]);
    }

    void update(int index, int val) {
        int diff=val-arr[index];
        arr[index]=val;
        init(index,diff);
    }

    int sumRange(int left, int right) {
        return sum(right)-sum(left-1);
    }
};
